import {
  dossierUrlRegExp,
  libraryUrlRegExp,
  exampleSearchUrlRegExp,
} from '../constants/urls-regexp';
import EmbeddingType from './embeddingType';
// Modifies the given text to replace all strings in the array oldValues with the strings in newValues
const textReplaceAll = (text, oldValues, newValues) => {
  if (text) {
    let output = text;
    for (let i = 0; i < oldValues.length; i += 1) {
      output = output.replaceAll(oldValues[i], newValues[i]);
    }
    return output;
  }
  return text;
};
// Parse the example url used to display the example popup and return the exampleId uppercased
export const parseExampleIdFromSearchURI = (url) => {
  const urlMatched = url.match(exampleSearchUrlRegExp);
  let exampleId = urlMatched?.groups?.exampleId || '';
  exampleId = exampleId.toLowerCase();
  return exampleId;
};

function retrieveItemsFromMatchedUrl(url, urlMatched) {
  const baseServerUrl = urlMatched?.groups?.baseServerUrl || '';
  const libraryName = urlMatched?.groups?.libraryName || '';
  const projectID = urlMatched?.groups?.projectID || '';
  const dossierID = urlMatched?.groups?.dossierID || '';
  const applicationId = urlMatched?.groups?.configID || '';
  const libraryUrl = `${baseServerUrl}/${libraryName}`;
  const embeddinglibjsUrl = `${libraryUrl}/javascript/embeddinglib.js`;
  const dashboardUrl = url;

  return {
    dashboardUrl,
    baseServerUrl,
    libraryName,
    libraryUrl,
    embeddinglibjsUrl,
    projectID,
    dossierID,
    applicationId,
  };
}

// Parse the dashboard url and return the object {baseServerUrl, libraryName, and embeddinglibjsUrl}
export const parseDossierUrl = (url) => {
  const urlMatched = url.match(dossierUrlRegExp);
  return retrieveItemsFromMatchedUrl(url, urlMatched);
};

export const parseLibraryUrl = (url) => {
  const urlMatched = url.match(libraryUrlRegExp);
  return retrieveItemsFromMatchedUrl(url, urlMatched);
};

function handleQueryParams(url, queryParams, separator = '&') {
  let newUrl = url;
  const queryString = Object.keys(queryParams)
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(queryParams[key])}`)
    .join(separator);
  if (queryString) {
    newUrl = `${newUrl} + '?${queryString}'`;
  }
  return newUrl;
}

/**
 * Creates the html string given relativePath of the template and can replace the defaultUrl in template along with the embeddinglibjs url
 * Input: (relativePath: string required rest are optional, defaultUrl: string, url: string,)
 * Output: string
 */
const populateEnvInfo = (template, embeddingType, envSettingInfo, defaultEnvInfo) => {
  let templateStr = template;
  const defaultParsedUrl = parseDossierUrl(defaultEnvInfo.defaultUrl); // Returns an object containing {baseServerUrl, libraryName, and embeddinglibjsUrl} from given url
  const parsedUrl = parseDossierUrl(envSettingInfo.customUrl);
  // for these types we need handle the input of url
  if (EmbeddingType.Dashboard === embeddingType) {
    const currentStrings = [defaultParsedUrl.dashboardUrl, defaultParsedUrl.embeddinglibjsUrl];
    const newStrings = [parsedUrl.dashboardUrl, parsedUrl.embeddinglibjsUrl];

    // Outputs the content of the text file after replacing the currentStrings with newStrings
    templateStr = textReplaceAll(templateStr, currentStrings, newStrings);
  }
  // for these types we need to parse the url and replace the projectID and dossierID
  if (
    [
      EmbeddingType.Bot,
      EmbeddingType.Bot_Api,
      EmbeddingType.Visualization,
      EmbeddingType.NextGet_AI,
      EmbeddingType.NextGet_AI_WithViz,
    ].includes(embeddingType)
  ) {
    const oldProjectId = defaultEnvInfo.projectId;
    const oldObjectId = defaultEnvInfo.objectId;
    const currentStrings = [
      oldProjectId,
      oldObjectId,
      defaultEnvInfo.defaultUrl,
      defaultParsedUrl.embeddinglibjsUrl,
      'loginMode: 8',
    ];
    const newStrings = [
      parsedUrl.projectID,
      parsedUrl.dossierID,
      parsedUrl.libraryUrl,
      parsedUrl.embeddinglibjsUrl,
      'loginMode: 1',
    ];
    templateStr = textReplaceAll(templateStr, currentStrings, newStrings);
  }
  // for these types we need handle the input of username and password
  if (
    [
      EmbeddingType.Bot_Api,
      EmbeddingType.Bot_Auto,
      EmbeddingType.Bot_AutoImage,
      EmbeddingType.NextGet_AI,
      EmbeddingType.NextGet_AI_WithViz,
    ].includes(embeddingType)
  ) {
    const currentUsrPwd = [defaultEnvInfo.username, defaultEnvInfo.password];
    const newUsrPwd = [envSettingInfo.username, envSettingInfo.password];
    templateStr = textReplaceAll(templateStr, currentUsrPwd, newUsrPwd);
  }
  if (
    [EmbeddingType.Bot_Auto, EmbeddingType.Bot_AutoImage, EmbeddingType.Library].includes(
      embeddingType,
    )
  ) {
    const parsedLibUrl = parseLibraryUrl(envSettingInfo.customUrl);
    const defaultParsedLibUrl = parseLibraryUrl(defaultEnvInfo.defaultUrl);

    const currentStrings = [defaultParsedLibUrl.libraryUrl, defaultParsedLibUrl.embeddinglibjsUrl];
    const newStrings = [parsedLibUrl.libraryUrl, parsedLibUrl.embeddinglibjsUrl];

    // for Bot_Auto and Bot_AutoImage, we need to handle the query params
    if (embeddingType !== EmbeddingType.Library) {
      defaultEnvInfo.requestPhrases.forEach((currRequest) => {
        let newRequestUrl = currRequest;
        const queryParams = {};
        if (envSettingInfo.contentGroup) {
          queryParams.contentGroupIds = envSettingInfo.contentGroup;
        }
        if (parsedLibUrl.applicationId) {
          queryParams.applicationId = parsedLibUrl.applicationId;
        }
        newRequestUrl = handleQueryParams(currRequest, queryParams);
        currentStrings.push(currRequest);
        newStrings.push(newRequestUrl);
      });
    }
    templateStr = textReplaceAll(templateStr, currentStrings, newStrings);
  }
  return templateStr;
};

