const updateDuplicateCode = (code) => {
  let updatedCode = code;
  Object.keys(duplicateCodeMap).forEach((key) => {
    updatedCode = updatedCode.replace(key, duplicateCodeMap[key]);
  });
  return updatedCode;
};

const createDefaultTemplate = async (relativePath) => {
  let locationEndWithSlash = '';
  if (window.location && window.location.href && typeof window.location.href === 'string') {
    locationEndWithSlash = window.location.href.endsWith('/')
      ? window.location.href
      : `${window.location.href}/`;
  }
  const absolutePath = locationEndWithSlash + relativePath;
  const response = await fetch(absolutePath);
  const template = await response.text();
  return updateDuplicateCode(template);
};

