// Function that generates the initial code for the template
export const templateInitialCode = (
  embeddingType = EmbeddingType.Dashboard,
  exampleName = exampleTemplates.dashboard.content.general.items.simpleExample.name,
  exampleGroupName = exampleTemplates.dashboard.content.general.groupName,
) => {
  let initialCode = '';

  // Loop through the exampleTemplates to find the specified template based on exampleGroupName and exampleName
  // then get the initial code for that template
  Object.values(
    Object.values(exampleTemplates).find((example) => example.embeddingType === embeddingType)
      .content,
  ).forEach((exampleGroup) => {
    if (exampleGroup.groupName === exampleGroupName && exampleGroup.items) {
      Object.values(exampleGroup.items).forEach((example) => {
        if (example.name === exampleName) {
          // Use the defaultUrl in template used for demos
          initialCode = example.defaultTemplate();
        }
      });
    }
  });

  return initialCode;
};

export const embeddingTypeToExampleMap = {
  [EmbeddingType.Dashboard]: exampleTemplates.dashboard.content.general.items.simpleExample,
  [EmbeddingType.Library]: exampleTemplates.library.content.general.items.simpleExample,
  [EmbeddingType.Visualization]: exampleTemplates.visualization.content.general.items.simpleExample,
  [EmbeddingType.Bot]: exampleTemplates.bot.content.general.items.simpleExample,
  [EmbeddingType.Bot_Api]: exampleTemplates.bot.content.general.items.botApiDemo,
  [EmbeddingType.Bot_Auto]: exampleTemplates.bot.content.general.items.unifiedBotApiDemo,
  [EmbeddingType.Bot_AutoImage]:
    exampleTemplates.bot.content.general.items.unifiedBotApiDemoWithImage,
  [EmbeddingType.NextGet_AI]: exampleTemplates.bot.content.general.items.nextGenAiDemo,
  [EmbeddingType.NextGet_AI_WithViz]:
    exampleTemplates.bot.content.general.items.nextGenAiDemoWithViz,
};

// Function that generates the initial code for the template
// TODO: add viz type handling
export const updateDefaultTemplateForEmbeddingType = async (
  embeddingType,
  envSettingInfo = null,
) => {
  let template;
  let templateStr = '';

  if (embeddingType in embeddingTypeToExampleMap) {
    template = embeddingTypeToExampleMap[embeddingType];
    templateStr = await template.defaultTemplate();
  } else {
    throw new Error('Invalid embedding type.');
  }
  if (envSettingInfo != null) {
    templateStr = populateEnvInfo(
      templateStr,
      embeddingType,
      envSettingInfo,
      template.defaultEnvInfo,
    );
  }

  return templateStr;
};
